begin;
create table public.arena_alliance_treasuries(alliance_id uuid primary key references public.arena_alliances(id)on delete cascade,gems bigint not null default 0 check(gems>=0),lifetime_gems bigint not null default 0 check(lifetime_gems>=0),updated_at timestamptz not null default now());
create table public.arena_alliance_funding_goals(id uuid primary key default gen_random_uuid(),alliance_id uuid not null references public.arena_alliances(id)on delete cascade,created_by uuid references public.profiles(id)on delete set null,title text not null check(length(trim(title))between 3 and 60),description text not null default''check(length(description)<=240),target_gems integer not null check(target_gems between 10 and 100000),funded_gems integer not null default 0 check(funded_gems>=0),status text not null default'active'check(status in('active','funded','archived')),created_at timestamptz not null default now());
create table public.arena_alliance_treasury_ledger(id uuid primary key default gen_random_uuid(),alliance_id uuid not null references public.arena_alliances(id)on delete cascade,actor_id uuid references public.profiles(id)on delete set null,goal_id uuid references public.arena_alliance_funding_goals(id)on delete set null,amount bigint not null check(amount<>0),entry_type text not null check(entry_type in('donation','purchase','refund','adjustment')),reference_id text,idempotency_key text not null unique,created_at timestamptz not null default now());create index arena_alliance_treasury_recent on public.arena_alliance_treasury_ledger(alliance_id,created_at desc);create index arena_alliance_goals_active on public.arena_alliance_funding_goals(alliance_id,status,created_at desc);
alter table public.arena_alliance_treasuries enable row level security;alter table public.arena_alliance_treasuries force row level security;alter table public.arena_alliance_funding_goals enable row level security;alter table public.arena_alliance_funding_goals force row level security;alter table public.arena_alliance_treasury_ledger enable row level security;alter table public.arena_alliance_treasury_ledger force row level security;revoke all on public.arena_alliance_treasuries,public.arena_alliance_funding_goals,public.arena_alliance_treasury_ledger from anon,authenticated;
create or replace function public.arena_get_alliance_treasury()returns jsonb language plpgsql security definer set search_path='' as $$declare v_user uuid:=(select auth.uid());v_alliance uuid;v_role text;v_wallet bigint;begin select alliance_id,role into v_alliance,v_role from public.arena_alliance_members where user_id=v_user;if v_alliance is null then raise exception'alliance required';end if;select gems into v_wallet from public.arena_player_wallets where user_id=v_user;insert into public.arena_alliance_treasuries(alliance_id)values(v_alliance)on conflict do nothing;return jsonb_build_object('balance',(select gems from public.arena_alliance_treasuries where alliance_id=v_alliance),'lifetime_gems',(select lifetime_gems from public.arena_alliance_treasuries where alliance_id=v_alliance),'wallet_gems',coalesce(v_wallet,0),'can_manage',v_role in('founder','elder'),'donated_today',(select coalesce(sum(amount),0)from public.arena_alliance_treasury_ledger where alliance_id=v_alliance and actor_id=v_user and entry_type='donation'and created_at>=current_date),'daily_limit',200,'goals',(select coalesce(jsonb_agg(to_jsonb(g)order by created_at desc),'[]'::jsonb)from(select id,title,description,target_gems,funded_gems,status,created_at from public.arena_alliance_funding_goals where alliance_id=v_alliance and status<>'archived')g),'ledger',(select coalesce(jsonb_agg(to_jsonb(l)order by created_at desc),'[]'::jsonb)from(select l.id,l.amount,l.entry_type,l.created_at,coalesce(p.display_name,'Sistema')actor_name,g.title goal_title from public.arena_alliance_treasury_ledger l left join public.profiles p on p.id=l.actor_id left join public.arena_alliance_funding_goals g on g.id=l.goal_id where l.alliance_id=v_alliance order by l.created_at desc limit 40)l));end;$$;
create or replace function public.arena_donate_alliance_gems(p_amount integer,p_goal_id uuid,p_idempotency_key text)returns jsonb language plpgsql security definer set search_path='' as $$declare v_user uuid:=(select auth.uid());v_alliance uuid;v_wallet public.arena_player_wallets%rowtype;v_today bigint;begin select alliance_id into v_alliance from public.arena_alliance_members where user_id=v_user;if v_alliance is null or p_amount not between 1 and 200 or length(coalesce(p_idempotency_key,''))<16 then raise exception'invalid donation';end if;if p_goal_id is not null and not exists(select 1 from public.arena_alliance_funding_goals where id=p_goal_id and alliance_id=v_alliance and status='active')then raise exception'goal unavailable';end if;if exists(select 1 from public.arena_alliance_treasury_ledger where idempotency_key=p_idempotency_key)then return jsonb_build_object('donated',true,'replayed',true);end if;select coalesce(sum(amount),0)into v_today from public.arena_alliance_treasury_ledger where alliance_id=v_alliance and actor_id=v_user and entry_type='donation'and created_at>=current_date;if v_today+p_amount>200 then raise exception'daily limit';end if;insert into public.arena_player_wallets(user_id)values(v_user)on conflict(user_id)do nothing;select*into v_wallet from public.arena_player_wallets where user_id=v_user for update;if v_wallet.gems<p_amount then raise exception'insufficient gems';end if;update public.arena_player_wallets set gems=gems-p_amount where user_id=v_user;insert into public.arena_wallet_transactions(user_id,currency,amount,transaction_type,source,reference_id,idempotency_key)values(v_user,'gems',-p_amount,'spend','alliance-treasury',v_alliance::text,'wallet:'||p_idempotency_key);insert into public.arena_alliance_treasuries(alliance_id,gems,lifetime_gems)values(v_alliance,p_amount,p_amount)on conflict(alliance_id)do update set gems=public.arena_alliance_treasuries.gems+p_amount,lifetime_gems=public.arena_alliance_treasuries.lifetime_gems+p_amount,updated_at=now();insert into public.arena_alliance_treasury_ledger(alliance_id,actor_id,goal_id,amount,entry_type,idempotency_key)values(v_alliance,v_user,p_goal_id,p_amount,'donation',p_idempotency_key);if p_goal_id is not null then update public.arena_alliance_funding_goals set funded_gems=least(target_gems,funded_gems+p_amount),status=case when funded_gems+p_amount>=target_gems then'funded'else'active'end where id=p_goal_id;end if;update public.arena_alliance_members set contribution=contribution+p_amount where alliance_id=v_alliance and user_id=v_user;return jsonb_build_object('donated',true,'amount',p_amount);end;$$;
create or replace function public.arena_create_alliance_funding_goal(p_title text,p_description text,p_target_gems integer)returns uuid language plpgsql security definer set search_path='' as $$declare v_user uuid:=(select auth.uid());v_alliance uuid;v_role text;v_id uuid;begin select alliance_id,role into v_alliance,v_role from public.arena_alliance_members where user_id=v_user;if v_alliance is null or v_role not in('founder','elder')then raise exception'alliance manager required';end if;if(select count(*)from public.arena_alliance_funding_goals where alliance_id=v_alliance and status='active')>=3 then raise exception'too many goals';end if;insert into public.arena_alliance_funding_goals(alliance_id,created_by,title,description,target_gems)values(v_alliance,v_user,trim(p_title),left(trim(coalesce(p_description,'')),240),p_target_gems)returning id into v_id;return v_id;end;$$;
create or replace function public.arena_archive_alliance_funding_goal(p_goal_id uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare v_user uuid:=(select auth.uid());v_alliance uuid;v_role text;begin select alliance_id,role into v_alliance,v_role from public.arena_alliance_members where user_id=v_user;if v_alliance is null or v_role not in('founder','elder')then raise exception'alliance manager required';end if;update public.arena_alliance_funding_goals set status='archived'where id=p_goal_id and alliance_id=v_alliance;if not found then raise exception'goal unavailable';end if;return jsonb_build_object('archived',true);end;$$;
revoke all on function public.arena_get_alliance_treasury(),public.arena_donate_alliance_gems(integer,uuid,text),public.arena_create_alliance_funding_goal(text,text,integer),public.arena_archive_alliance_funding_goal(uuid)from public;grant execute on function public.arena_get_alliance_treasury(),public.arena_donate_alliance_gems(integer,uuid,text),public.arena_create_alliance_funding_goal(text,text,integer),public.arena_archive_alliance_funding_goal(uuid)to authenticated;
commit;
